/**
 * P1-2 geocoder bias contract — frontend half (locked, written before
 * implementation per WORKING_RULES.md "Mimari Bağlam Zorunluluğu").
 *
 * Mirrors tulipfleet-enterprise-backend/test/geocode.bias.test.js: the hook
 * must forward an optional bias center to the backend's `at=lat,lng` query
 * param, and must not send a malformed one. Do not edit this file to make
 * it pass — edit useGeocodeSearch.ts.
 *
 * Run (Windows, per WORKING_RULES "npm install/ci/build Windows'ta koşulur"):
 *   npm test -- useGeocodeSearch --watchAll=false
 */
import { act, renderHook, waitFor } from "@testing-library/react";
import { useGeocodeSearch } from "./useGeocodeSearch";

jest.mock("store/useAuthStore", () => ({
  useAuthStore: (selector: (s: { token: string }) => unknown) => selector({ token: "test-jwt" }),
}));

function mockFetchOnce(body: unknown) {
  (global.fetch as jest.Mock).mockResolvedValueOnce({
    ok: true,
    json: async () => body,
  });
}

beforeEach(() => {
  jest.useFakeTimers();
  global.fetch = jest.fn();
});

afterEach(() => {
  jest.useRealTimers();
  jest.clearAllMocks();
});

async function flushDebounce() {
  await act(async () => {
    jest.advanceTimersByTime(300);
  });
}

test("without a bias, the request carries no `at` param (back-compat)", async () => {
  mockFetchOnce({ results: [] });
  const { rerender } = renderHook(({ q }) => useGeocodeSearch(q), {
    initialProps: { q: "Waalhaven" },
  });
  await flushDebounce();
  await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(1));

  const [url] = (global.fetch as jest.Mock).mock.calls[0];
  expect(new URL(String(url)).searchParams.has("at")).toBe(false);
  rerender({ q: "Waalhaven" });
});

test("a valid bias is forwarded as `at=lat,lng`", async () => {
  mockFetchOnce({ results: [] });
  renderHook(
    ({ q, biasAt }) => useGeocodeSearch(q, biasAt),
    {
      initialProps: {
        q: "Waalhaven",
        biasAt: { latitude: 51.92, longitude: 4.48 } as { latitude: number; longitude: number } | null,
      },
    }
  );
  await flushDebounce();
  await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(1));

  const [url] = (global.fetch as jest.Mock).mock.calls[0];
  expect(new URL(String(url)).searchParams.get("at")).toBe("51.92,4.48");
});

test("a null/undefined bias omits `at` — same request shape as today", async () => {
  mockFetchOnce({ results: [] });
  renderHook(({ q }) => useGeocodeSearch(q, null), {
    initialProps: { q: "Waalhaven" },
  });
  await flushDebounce();
  await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(1));

  const [url] = (global.fetch as jest.Mock).mock.calls[0];
  expect(new URL(String(url)).searchParams.has("at")).toBe(false);
});

test("a non-finite bias (NaN lat/lng) is dropped, not sent as `at=NaN,NaN`", async () => {
  mockFetchOnce({ results: [] });
  renderHook(
    ({ q, biasAt }) => useGeocodeSearch(q, biasAt),
    {
      initialProps: {
        q: "Waalhaven",
        biasAt: { latitude: NaN, longitude: 4.48 },
      },
    }
  );
  await flushDebounce();
  await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(1));

  const [url] = (global.fetch as jest.Mock).mock.calls[0];
  expect(new URL(String(url)).searchParams.has("at")).toBe(false);
});

test("changing the bias while the query stays the same re-queries (new `at`, fresh ranking)", async () => {
  mockFetchOnce({ results: [] });
  const { rerender } = renderHook(
    ({ q, biasAt }) => useGeocodeSearch(q, biasAt),
    {
      initialProps: {
        q: "Waalhaven",
        biasAt: { latitude: 51.92, longitude: 4.48 },
      },
    }
  );
  await flushDebounce();
  await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(1));

  mockFetchOnce({ results: [] });
  rerender({ q: "Waalhaven", biasAt: { latitude: 52.37, longitude: 4.9 } });
  await flushDebounce();
  await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(2));

  const [secondUrl] = (global.fetch as jest.Mock).mock.calls[1];
  expect(new URL(String(secondUrl)).searchParams.get("at")).toBe("52.37,4.9");
});

test("results carry city/postalCode/countryCode/distanceM through untouched", async () => {
  mockFetchOnce({
    results: [
      {
        title: "Waalhaven Zuidzijde",
        addressLabel: "Waalhaven Zuidzijde, 3089 JH Rotterdam, Netherlands",
        latitude: 51.8929,
        longitude: 4.4489,
        city: "Rotterdam",
        postalCode: "3089 JH",
        countryCode: "NLD",
        distanceM: 3100,
      },
    ],
  });
  const { result } = renderHook(
    ({ q, biasAt }) => useGeocodeSearch(q, biasAt),
    {
      initialProps: {
        q: "Waalhaven",
        biasAt: { latitude: 51.92, longitude: 4.48 },
      },
    }
  );
  await flushDebounce();
  await waitFor(() => expect(result.current.results.length).toBe(1));

  expect(result.current.results[0]).toMatchObject({
    city: "Rotterdam",
    postalCode: "3089 JH",
    countryCode: "NLD",
    distanceM: 3100,
  });
});
